"use client";

import { useId } from "react";

import { PlayerPlayFilledIcon } from "@/components/blocks/parts/icons";
import { NumberTicker } from "@/components/motion/number-ticker";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatOnePlace } from "../lib/format";
import { STATUS_TEXT } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { StopIcon } from "./icons";
import { formatSeconds, ROLL_CENTS, ROLL_ONE_PLACE } from "./lib/format";
import { CategoryRow } from "./eval-suite/category-row";
import { ChangeList } from "./eval-suite/change-list";
import {
  BASELINE_SCORE,
  CASES,
  CATEGORIES,
  COST_PER_CASE,
  HISTORY,
  MODELS,
  RUN_ORDER,
  SECONDS_PER_CASE,
  VERSIONS,
} from "./eval-suite/data";
import { HistoryChart } from "./eval-suite/history-chart";
import { useEvalRun } from "./eval-suite/use-eval-run";

const STATUS_LINE = {
  idle: "Not run yet",
  running: "Running",
  stopped: "Stopped",
  done: "Finished",
} as const;

/**
 * Runs a test suite on a new version of the Fernhill booking assistant
 * against the current one. Results stream in case by case into a grid per
 * category, the score and cost roll as they land, and the cases that got
 * worse or were fixed are listed with a drilldown to triage each one.
 */
export function EvalSuite({ className }: { className?: string }) {
  const { status, finished, cellStates, elapsed, run, stop } = useEvalRun();
  const titleId = useId();

  const landed = RUN_ORDER.slice(0, finished).map((index) => CASES[index]!);
  const passed = landed.filter((item) => item.candidatePass).length;
  const score = finished === 0 ? 0 : (passed / finished) * 100;
  const changes = landed.filter((item) => item.candidatePass !== item.baselinePass && item.judgeNote);
  const gap = score - BASELINE_SCORE;
  const runs = status === "done" ? [...HISTORY.slice(1), { version: VERSIONS.candidate, score }] : HISTORY;
  const running = status === "running";

  const announce =
    status === "idle"
      ? ""
      : status === "running"
        ? `${finished} of ${CASES.length} cases finished`
        : `${STATUS_LINE[status]}. ${finished} of ${CASES.length} cases, score ${formatOnePlace(score)}%, ${changes.length} changed cases.`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Booking assistant
          </h2>
          <p className="text-sm text-muted-foreground">
            {VERSIONS.candidate} against {VERSIONS.baseline}, {CASES.length} test cases
          </p>
          <p className="mt-2 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-muted-foreground">
            <span className="rounded-md border border-border px-2 py-0.5 text-foreground">{MODELS.candidate}</span>
            against
            <span className="rounded-md border border-border px-2 py-0.5 text-foreground">{MODELS.baseline}</span>
            graded by
            <span className="rounded-md border border-border px-2 py-0.5 text-foreground">{MODELS.judge}</span>
          </p>
        </div>
        <Button onClick={running ? stop : run} variant={running ? "outline" : "default"}>
          {running ? <StopIcon aria-hidden="true" /> : <PlayerPlayFilledIcon aria-hidden="true" />}
          {running ? "Stop" : status === "idle" ? "Run suite" : "Run again"}
        </Button>
      </header>

      <div className="grid gap-px border-b border-border bg-border @2xl:grid-cols-[1fr_1.3fr_1fr]">
        <div className="flex flex-col gap-1 bg-card px-5 py-4">
          <h3 className="text-sm text-muted-foreground">Score</h3>
          {finished === 0 ? (
            <p className="text-2xl font-semibold tracking-tight">{STATUS_LINE[status]}</p>
          ) : (
            <p className="text-2xl font-semibold tracking-tight tabular-nums">
              <NumberTicker value={score} format={ROLL_ONE_PLACE} />%
            </p>
          )}
          <p className="text-xs text-muted-foreground">
            {MODELS.baseline} scored {formatOnePlace(BASELINE_SCORE)}%
            {finished === 0 ? null : (
              <span className={cn("ml-1 font-medium", STATUS_TEXT[gap >= 0 ? "good" : "bad"])}>
                {gap >= 0 ? "up" : "down"} {formatOnePlace(Math.abs(gap))} points
              </span>
            )}
          </p>
        </div>
        <div className="flex min-w-0 flex-col gap-2 bg-card px-5 py-4">
          <h3 className="text-sm text-muted-foreground">Last {runs.length} runs</h3>
          <HistoryChart runs={runs} baseline={BASELINE_SCORE} />
        </div>
        <dl className="grid grid-cols-2 gap-x-4 gap-y-1 bg-card px-5 py-4 @2xl:grid-cols-1">
          <div>
            <dt className="text-sm text-muted-foreground">Cost</dt>
            <dd className="text-base font-semibold tabular-nums">
              {status === "idle" ? `About ${(CASES.length * COST_PER_CASE).toLocaleString("en-US", { style: "currency", currency: "USD" })}` : <NumberTicker value={finished * COST_PER_CASE} format={ROLL_CENTS} />}
            </dd>
          </div>
          <div>
            <dt className="text-sm text-muted-foreground">Time</dt>
            <dd className="text-base font-semibold tabular-nums">
              {status === "idle" ? `About ${formatSeconds(CASES.length * SECONDS_PER_CASE)}` : formatSeconds(elapsed)}
            </dd>
          </div>
        </dl>
      </div>

      <p role="status" className="sr-only">
        {announce}
      </p>
      <div className="flex items-center justify-between px-5 pt-4 text-xs text-muted-foreground">
        <span aria-hidden="true" className="tabular-nums">
          {finished} of {CASES.length} cases
        </span>
        <span className="flex items-center gap-3">
          <span className="flex items-center gap-1.5">
            <span aria-hidden="true" className="flex gap-0.5">
              <span className="size-2.5 rounded-sm bg-chart-1" />
              <span className="size-2.5 rounded-sm bg-chart-3" />
              <span className="size-2.5 rounded-sm bg-chart-5" />
            </span>
            Passed
          </span>
          <span className="flex items-center gap-1.5">
            <span aria-hidden="true" className={cn("size-2.5 rounded-sm border border-current", STATUS_TEXT.bad)} />
            Failed
          </span>
        </span>
      </div>
      <ul aria-label="Results by category" className="group/grid flex flex-col py-2">
        {CATEGORIES.map((category) => (
          <CategoryRow
            key={category.id}
            category={category}
            cells={cellStates.filter((_, index) => CASES[index]?.category === category.id)}
          />
        ))}
      </ul>

      <ChangeList changes={changes} started={status !== "idle"} />
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

