/** One decimal place, for a score or a percent. */
export const ROLL_ONE_PLACE: Intl.NumberFormatOptions = { minimumFractionDigits: 1, maximumFractionDigits: 1 };
/** Dollars with cents. */
export const ROLL_CENTS: Intl.NumberFormatOptions = { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 };

"use client";

import { motion, useReducedMotion } from "motion/react";

import { XIcon } from "@/components/blocks/parts/icons";
import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../../lib/status";
import { ROLL_WHOLE } from "../lib/format";
import type { Category } from "./data";
import type { CellState } from "./use-eval-run";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

// A fixed small square with its own corner, so a design system with large radii does not turn the cells into circles.
const CELL = "size-4 shrink-0 rounded-sm";

/** Props for one category of the test grid. */
export interface CategoryRowProps {
  category: Category;
  /** The state of each case in the category, in case order. */
  cells: CellState[];
}

/**
 * One category: its name, the share of finished cases that passed with a bar
 * in the category's hue, and one cell per case. A finished cell scales in,
 * filled in the category hue for a pass, or outlined in orange with a cross for a fail; a case in flight pulses.
 */
export function CategoryRow({ category, cells }: CategoryRowProps) {
  const reduceMotion = useReducedMotion();
  const done = cells.filter((cell) => cell === "pass" || cell === "fail").length;
  const passed = cells.filter((cell) => cell === "pass").length;
  const percent = done === 0 ? 0 : Math.round((passed / done) * 100);

  return (
    <li className="grid grid-cols-[1fr_auto] items-center gap-x-4 gap-y-2 px-5 py-3 motion-safe:transition-opacity group-hover/grid:opacity-50 hover:opacity-100! @2xl:grid-cols-[11rem_1fr_6.5rem]">
      <span className="truncate text-sm font-medium">{category.name}</span>
