/** All test cases, in a fixed order. */
export const CASES: EvalCase[] = CATEGORIES.flatMap((category) =>
  Array.from({ length: PER_CATEGORY }, (_, slot) => {
    const id = `${category.id}-${slot}`;
    const regression = REGRESSIONS.find((story) => story.category === category.id && story.slot === slot);
    const fix = FIXES.find((story) => story.category === category.id && story.slot === slot);
    const story = regression ?? fix;
    const fails = BOTH_FAIL.has(id);
    return {
      id,
      category: category.id,
      prompt: story?.prompt ?? `${category.name} case ${slot + 1}`,
      baselinePass: regression ? true : fix ? false : !fails,
      candidatePass: regression ? false : fix ? true : !fails,
      baselineAnswer: story?.baselineAnswer,
      candidateAnswer: story?.candidateAnswer,
      judgeNote: story?.judgeNote,
    };
  }),
);

/** The order the run finishes cases in: a fixed shuffle, so cases land across the grid rather than row by row. */
export const RUN_ORDER: number[] = (() => {
  const order = CASES.map((_, index) => index);
  let seed = 7;
  for (let index = order.length - 1; index > 0; index -= 1) {
    seed = (seed * 9301 + 49297) % 233280;
    const swap = Math.floor((seed / 233280) * (index + 1));
    [order[index], order[swap]] = [order[swap]!, order[index]!];
  }
  return order;
})();

