"use client";

import { useState } from "react";

import { useElapsed, useInterval } from "../lib/timers";
import { CASES, RUN_ORDER } from "./data";

/** Where a run is. */
export type RunStatus = "idle" | "running" | "stopped" | "done";

/** The state of one case cell in the grid. */
export type CellState = "pending" | "running" | "pass" | "fail";

// At most this many cases are in flight at once.
const PARALLEL = 4;
const TICK = 120;

/**
 * Simulates a run that streams results case by case. Cases start in a fixed
 * shuffled order, up to four at a time, and land one or two per tick. Stopping
 * keeps what has landed; Run starts again from nothing.
 */
export function useEvalRun() {
  const [status, setStatus] = useState<RunStatus>("idle");
  const [finished, setFinished] = useState(0);
  const [runKey, setRunKey] = useState(0);
  const elapsed = useElapsed(status === "running", runKey);

  useInterval(
    () => {
      // A tick lands one case, and every third tick lands two, so results arrive unevenly.
      const next = Math.min(CASES.length, finished + (finished % 3 === 0 ? 2 : 1));
      setFinished(next);
      if (next >= CASES.length) setStatus("done");
    },
    status === "running" ? TICK : null,
  );

  const started = status === "running" ? Math.min(CASES.length, finished + PARALLEL) : finished;
  const cellStates: CellState[] = CASES.map(() => "pending");
  RUN_ORDER.forEach((caseIndex, position) => {
    const item = CASES[caseIndex];
    if (!item) return;
    if (position < finished) cellStates[caseIndex] = item.candidatePass ? "pass" : "fail";
    else if (position < started) cellStates[caseIndex] = "running";
  });

  const run = () => {
    setFinished(0);
    setRunKey((key) => key + 1);
    setStatus("running");
  };
  const stop = () => setStatus("stopped");

  return { status, finished, cellStates, elapsed, run, stop };
}

