/** Props for a region that opens to its full height. */
export interface RevealProps {
  open: boolean;
  children: ReactNode;
  /** An id, so the control that opens it can point at it with `aria-controls`. */
  id?: string;
  className?: string;
}

// Critically damped: 2 * sqrt(380) is about 39, so the height lands without a wobble.
const HEIGHT: Transition = { type: "spring", stiffness: 380, damping: 39, mass: 1 };

/**
 * Opens from zero to its full height on a critically damped spring. The
 * content fades in a beat after the height starts and fades out a beat before
 * it ends, and rises a little into place. With reduced motion it appears at once.
 */
export function Reveal({ open, children, id, className }: RevealProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AnimatePresence initial={false}>
      {open ? (
        <motion.div
          key="reveal"
          id={id}
          initial={reduceMotion ? false : { height: 0 }}
          animate={{ height: "auto", transition: reduceMotion ? { duration: 0 } : HEIGHT }}
          exit={reduceMotion ? { height: 0, transition: { duration: 0 } } : { height: 0, transition: { ...HEIGHT, delay: 0.05 } }}
          className="overflow-hidden"
        >
          <motion.div
            initial={reduceMotion ? false : { opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0, transition: { duration: 0.18, delay: reduceMotion ? 0 : 0.06 } }}
            exit={{ opacity: 0, y: reduceMotion ? 0 : 4, transition: { duration: reduceMotion ? 0 : 0.12 } }}
            className={cn(className)}
          >
            {children}
          </motion.div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

